const DEFAULT_VIEW_SETTINGS={thisThen:{showCounts:false,showTrafficLights:true,showPriorities:true,showHowCounts:true,showMeasures:false,showEvalQuestions:false,showMainText:false,showLateralHow:false},how:{showNumbering:true,showTrafficLights:true,showPriorities:true,showWhyCounts:true,showLateralHow:false,showMeasures:false,showEvalQuestions:false,showMainText:false},finalOutcomes:{showTrafficLights:true,showPriorities:true,showMeasures:false,showEvalQuestions:false,showMainText:false}};
