// V1.0.12.8 (Fix 5): Sources popup is now editable. Each source is rendered as a pair of inputs (title, URL)
// with a remove control. Helper text replaces the older yellow warning-banner (.warn-txt) treatment and now
// uses standard popup-consistent styling (.info-helper). In display mode the user clicks the URL as a link;
// when editing, the row is a plain input. Save persists to the in-memory sources array and to localStorage.
// V1.0.14.1a (Fix 3): in editable boards, each non-empty URL also gets a small "Open" link beside the URL input so the user can open the saved URL in a new tab without entering edit mode (the URL input remains editable). In read-only copies, source rows render as view-only — the title appears as plain text, the URL appears as a clickable Open link (or as the bare URL if there is no title), and editable inputs / Add source / Save / Remove are hidden. The Close button on the modal remains so the popup can always be dismissed. The sources data shape and the saveSources/addNewSourceRow/removeSourceRow flow are unchanged for editable boards.
function openSources(){renderSourcesList();openModal('srcModal');}
function renderSourcesList(){var list=document.getElementById('srcList');if(!list)return;if(!sources.length){list.innerHTML='<div style="color:var(--text2);font-style:italic;font-size:13px;padding:6px 0">'+(IS_READONLY?'No sources.':'No sources added yet. Click "Add source" below to add one.')+'</div>';return;}var html='';sources.forEach(function(s,i){var t=(s&&s.title)||'';var u=(s&&s.url)||'';if(IS_READONLY){/* V1.0.14.1a (Fix 3): view-only row for read-only copies. Show title as plain text and URL as a clickable Open link. If only the URL is present, show the URL itself as the link text. */var titleHtml=t?'<span style="flex:1 1 180px;min-width:140px;font-size:13px;color:var(--text)">'+escHtml(t)+'</span>':'';var urlHtml='';if(u){var safeU=u.replace(/"/g,'&quot;');var openText=t?'Open':escHtml(u);urlHtml='<a href="'+safeU+'" target="_blank" rel="noopener" style="font-size:13px;color:var(--od);text-decoration:underline;word-break:break-all">'+openText+'</a>';}else if(!t){urlHtml='<span style="font-size:13px;color:var(--text2);font-style:italic">(no URL)</span>';}html+='<div class="src-view-row" data-idx="'+i+'" style="display:flex;gap:10px;align-items:center;margin-bottom:6px;flex-wrap:wrap;padding:4px 0">'+titleHtml+urlHtml+'</div>';}else{/* V1.0.14.1a (Fix 3): editable row gains a small Open link beside the URL input when the URL is non-empty, so the saved URL can be opened in a new tab without entering edit mode. The URL itself remains editable in the input. */var openLink=u?'<a href="'+escAttr(u)+'" target="_blank" rel="noopener" class="src-open-link" title="Open URL in new tab" style="font-size:12px;color:var(--od);text-decoration:underline;white-space:nowrap;padding:0 6px">Open</a>':'';html+='<div class="src-edit-row" data-idx="'+i+'" style="display:flex;gap:6px;align-items:center;margin-bottom:6px;flex-wrap:wrap">'
+'<input type="text" class="src-edit-title" value="'+escAttr(t)+'" placeholder="Title" style="flex:1 1 180px;min-width:140px;border:1px solid var(--bdr);border-radius:6px;padding:6px 9px;font-size:13px;font-family:inherit">'
+'<input type="text" class="src-edit-url" value="'+escAttr(u)+'" placeholder="Enter full URL, e.g. https://example.org" style="flex:2 1 260px;min-width:180px;border:1px solid var(--bdr);border-radius:6px;padding:6px 9px;font-size:13px;font-family:inherit">'
+openLink
+'<button class="ep-sbtn ep-del" onclick="removeSourceRow('+i+')" title="Remove">\u2715</button>'
+'</div>';}});list.innerHTML=html;}
function addNewSourceRow(){if(IS_READONLY)return;saveSourcesFromDOM(/*silent*/true);sources.push({title:'',url:''});renderSourcesList();}
function removeSourceRow(idx){if(IS_READONLY)return;saveSourcesFromDOM(/*silent*/true);if(idx<0||idx>=sources.length)return;sources.splice(idx,1);renderSourcesList();}
function saveSourcesFromDOM(silent){var rows=document.querySelectorAll('#srcList .src-edit-row');if(!rows||!rows.length){return;}var next=[];rows.forEach(function(row){var t=(row.querySelector('.src-edit-title')||{}).value||'';var u=(row.querySelector('.src-edit-url')||{}).value||'';t=t.trim();u=u.trim();if(!t&&!u)return;next.push({title:t,url:u});});sources=next;try{localStorage.setItem('doview_sources',JSON.stringify(sources));}catch(e){}if(!silent)saveState();}
