/* V1.0.12.9c (Fix 3): in read-only mode, popup windows still open and are viewable, but text/content fields inside them must be clearly non-editable. This helper sweeps the modal's textareas, text inputs, and contenteditable regions and disables editability, so typing or deletion inside popup fields is not possible when the change would not persist anyway. Links stay clickable; the Close button and navigation affordances are unaffected. A small .ro-keep-editable escape hatch is respected so viewing/filtering inputs (e.g. the global-search input) stay live. applyReadonlyToModal is called from openModal every time a modal opens, so dynamically-inserted content (Measure detail, EQ detail, Link detail, Sources list, Clone chooser, etc.) is covered after its innerHTML is set. */
function applyReadonlyToModal(modalEl){if(!IS_READONLY||!modalEl)return;try{var tas=modalEl.querySelectorAll('textarea');for(var i=0;i<tas.length;i++){var ta=tas[i];if(ta.classList&&ta.classList.contains('ro-keep-editable'))continue;ta.readOnly=true;ta.setAttribute('readonly','readonly');}var inputs=modalEl.querySelectorAll('input[type="text"]');for(var j=0;j<inputs.length;j++){var inp=inputs[j];if(inp.classList&&inp.classList.contains('ro-keep-editable'))continue;inp.readOnly=true;inp.setAttribute('readonly','readonly');}var ces=modalEl.querySelectorAll('[contenteditable="true"]');for(var k=0;k<ces.length;k++){ces[k].setAttribute('contenteditable','false');}}catch(e){}}
function openModal(id){var el=document.getElementById(id);if(!el)return;el.classList.add('open');applyReadonlyToModal(el);}
function closeModal(id){document.getElementById(id).classList.remove('open');}
