  var leftHtml=navBackBtn+navFwdBtn+'<strong>'+label+'</strong> \u00B7 <span class="pi-link" onclick="openPageInfo()">Page info</span>'+reorderBtn+viewBtn+delBtn+undoBtn;
  if(isSubpage){var _hlsp=SP.find(function(s){return s.id===pid;});if(_hlsp&&_hlsp.pageType==='how'){var hlv=_hlsp.howLevel;var howPages=SP.filter(function(s){return s.pageType==='how';});var lvlText=hlv?'Level '+hlv:'No level';var canUp=hlv&&hlv>1;var canDn=hlv&&hlv<howPages.filter(function(s){return s.howLevel;}).length;leftHtml+=' \u00B7 <span style="font-size:11px;color:var(--text2)">'+lvlText+'</span> <span class="pi-move" onclick="moveHowLevelUp(\''+pid+'\')" title="Move to higher level (lower number)" style="'+(canUp?'':'opacity:0.3;cursor:default;')+'">&#9650;</span><span class="pi-move" onclick="moveHowLevelDown(\''+pid+'\')" title="Move to lower level (higher number)" style="'+(canDn?'':'opacity:0.3;cursor:default;')+'">&#9660;</span><span class="pi-move" onclick="toggleHowLevel(\''+pid+'\')" title="Toggle level on/off" style="font-size:10px;margin-left:4px;text-decoration:underline">'+(hlv?'\u2715':'Set')+'</span>';}}
  // V1.0.12.13 (Fix 2): board-level Top right text rendered right-justified in the page-info bar. When non-empty, the text itself is shown (clickable in editable boards to edit, plain non-clickable in read-only mode). When empty, a modest "+ Add top right text" affordance was previously shown in editable boards only.
