function buildStateText(){const total=Object.keys(B).length;const green=Object.values(B).filter(v=>v.light==='green').length;const yellow=Object.values(B).filter(v=>v.light==='yellow').length;const red=Object.values(B).filter(v=>v.light==='red').length;let txt=`DOVIEW-STATE: ${TITLE}\nSlug: ${SLUG}\nSummary: ${green}/${total} green · ${yellow} yellow · ${red} red\n\nSTRUCTURE:\n`;SP.forEach(sp=>{txt+=`\n[${sp.id}] ${sp.label} | type:${sp.pageType||'this_then'}${sp.pageType==='how'&&sp.nextHowNum?' | nextHowNum:'+sp.nextHowNum:''}${sp.pageType==='how'&&sp.howLevel?' | howLevel:'+sp.howLevel:''} | bg:${spColor(sp).bg} bdr:${spColor(sp).bdr} tab:${spColor(sp).tab}\n`;if(sp.pageType==='how'&&sp.howBoxes){sp.howBoxes.forEach(hb=>{const k=`${sp.id}-${hb.id}`;const b=B[k];if(!b)return;const pri=b.priority?` | Pri:${b.priority}`:'';const entries=b.entries.length?' | '+b.entries.map(e=>`[${e.type}] ${e.text}`).join(' | '):'';const dt=b.detailText?` | [detail] ${b.detailText}`:'';const bc=b.borderColor?` | [border] ${b.borderColor}`:'';txt+=`    ${k} | ${b.light}${pri} | ${b.label}${entries}${dt}${bc}\n`;});}else{sp.cols.forEach((col,ci)=>{txt+=`  Column ${ci+1}: "${col.h}"\n`;col.boxes.forEach((_,bi)=>{const k=`${sp.id}-c${ci}-b${bi}`;const b=B[k];if(!b)return;const pri=b.priority?` | Pri:${b.priority}`:'';const entries=b.entries.length?' | '+b.entries.map(e=>`[${e.type}] ${e.text}`).join(' | '):'';const dt=b.detailText?` | [detail] ${b.detailText}`:'';const bc=b.borderColor?` | [border] ${b.borderColor}`:'';txt+=`    ${k} | ${b.light}${pri} | ${b.label}${entries}${dt}${bc}\n`;});});}});txt+=`\nFINAL OUTCOMES:\n`;FO_DATA.forEach((label,i)=>{const k=`final-b${i}`;const b=B[k];if(!b)return;const pri=b.priority?` | Pri:${b.priority}`:'';const entries=b.entries.length?' | '+b.entries.map(e=>`[${e.type}] ${e.text}`).join(' | '):'';const dt=b.detailText?` | [detail] ${b.detailText}`:'';const bc=b.borderColor?` | [border] ${b.borderColor}`:'';txt+=`  ${k} | ${b.light}${pri} | ${label}${entries}${dt}${bc}\n`;});if(boardInfo)txt+=`\nBOARD INFO:\n${boardInfo}\n`;if(topRightText)txt+=`\nTOP RIGHT TEXT:\n${topRightText}\n`;const piKeys=Object.keys(pageInfo).filter(k=>pageInfo[k]);if(piKeys.length){txt+=`\nPAGE INFO:\n`;piKeys.forEach(pid=>{let label=pid;if(pid==='overview')label='Overview';else if(pid==='final')label='Final Outcomes';else{const sp=SP.find(s=>s.id===pid);if(sp)label=sp.label;}txt+=`  [${label} (${pid})]: ${pageInfo[pid]}\n`;});}const _bstDcKeys=Object.keys(docContent).filter(k=>docContent[k]);if(_bstDcKeys.length){txt+=`\nDOCUMENTATION CONTENT:\n`;_bstDcKeys.forEach(pid=>{let label=pid;const sp=SP.find(s=>s.id===pid);if(sp)label=sp.label;txt+=`  [${label} (${pid})]: ${docContent[pid]}\n`;});}if(ttLinks.length){txt+=`\nTHIS-THEN LINKS:\n`;ttLinks.forEach(l=>{const fb=B[l.from];const tb=B[l.to];if(fb&&tb)txt+=`  ${l.id} | ${l.from} -> ${l.to} | ${fb.label} -> ${tb.label}${l.mainText?' | main:'+l.mainText:''}${l.notes1?' | n1:'+l.notes1:''}${l.notes2?' | n2:'+l.notes2:''}${l.notes3?' | n3:'+l.notes3:''}${l.measures&&l.measures.length?' | measures:'+l.measures.join(','):''}${l.evalQuestions&&l.evalQuestions.length?' | evalQuestions:'+l.evalQuestions.join(','):''}\n`;});txt+=`  nextId: ${ttLinkNextId}\n`;}if(howLinks.length){txt+=`\nHOW LINKS:\n`;howLinks.forEach(l=>{const fb=B[l.from];const tb=B[l.to];if(fb&&tb)txt+=`  ${l.id} | ${l.from} -> ${l.to} | ${fb.label} -> ${tb.label}${l.mainText?' | main:'+l.mainText:''}${l.notes1?' | n1:'+l.notes1:''}${l.notes2?' | n2:'+l.notes2:''}${l.notes3?' | n3:'+l.notes3:''}\n`;});txt+=`  nextId: ${howLinkNextId}\n`;}if(measures.length){txt+=`\nMEASURES:\n`;measures.forEach(m=>{const cnt=getBoxesLinkedToMeasure(m.id).length;txt+=`  ${m.id} | ${m.title} | linked:${cnt}${m.mainText?' | main:'+m.mainText:''}${m.notes1?' | n1:'+m.notes1:''}${m.notes2?' | n2:'+m.notes2:''}${m.notes3?' | n3:'+m.notes3:''}\n`;});txt+=`  nextId: ${measureNextId}\n`;}if(evalQuestions.length){txt+=`\nEVALUATION QUESTIONS:\n`;evalQuestions.forEach(q=>{const cnt=getBoxesLinkedToEQ(q.id).length;txt+=`  ${q.id} | ${q.questionText} | linked:${cnt}${q.mainText?' | main:'+q.mainText:''}${q.notes1?' | n1:'+q.notes1:''}${q.notes2?' | n2:'+q.notes2:''}${q.notes3?' | n3:'+q.notes3:''}\n`;});txt+=`  nextId: ${eqNextId}\n`;}txt+=`\nBOX MEASURES/EQ LINKS:\n`;Object.keys(B).forEach(k=>{const b=B[k];if(b.measures&&b.measures.length)txt+=`  ${k} measures: ${b.measures.join(',')}\n`;if(b.evalQuestions&&b.evalQuestions.length)txt+=`  ${k} evalQuestions: ${b.evalQuestions.join(',')}\n`;});txt+=`\nVIEW SETTINGS:\n  thisThen: showCounts=${viewSettings.thisThen.showCounts} showTrafficLights=${viewSettings.thisThen.showTrafficLights} showPriorities=${viewSettings.thisThen.showPriorities} showHowCounts=${viewSettings.thisThen.showHowCounts} showMeasures=${viewSettings.thisThen.showMeasures} showEvalQuestions=${viewSettings.thisThen.showEvalQuestions} showMainText=${viewSettings.thisThen.showMainText}\n  how: showNumbering=${viewSettings.how.showNumbering} showTrafficLights=${viewSettings.how.showTrafficLights} showPriorities=${viewSettings.how.showPriorities} showWhyCounts=${viewSettings.how.showWhyCounts} showLateralHow=${viewSettings.how.showLateralHow!==false} showMeasures=${viewSettings.how.showMeasures} showEvalQuestions=${viewSettings.how.showEvalQuestions} showMainText=${viewSettings.how.showMainText}\n  finalOutcomes: showTrafficLights=${viewSettings.finalOutcomes.showTrafficLights} showPriorities=${viewSettings.finalOutcomes.showPriorities} showMeasures=${viewSettings.finalOutcomes.showMeasures} showEvalQuestions=${viewSettings.finalOutcomes.showEvalQuestions} showMainText=${viewSettings.finalOutcomes.showMainText}\n`;txt+=`\n---\nWhen the user types 'redraw doview', rebuild this board using the uploaded doview-board-engine.js file. Reconstruct the full config from the structure above: each [pN] block is a subpage with its colors, each "Column N" is a column with heading, each indented line is a box with its ID, light state, priority, label, and entries. Pass all states via savedState in the DoView.init() config. Include howLinks and howLinkNextId in savedState if HOW LINKS section is present. Include viewSettings in savedState if VIEW SETTINGS section is present.`;return txt;}
function saveToClaud(){if(IS_READONLY)return;const txt=buildStateText();if(typeof sendPrompt==='function'){sendPrompt(txt);const btn=document.getElementById('saveBtn2');if(btn){btn.textContent='\u2713 Sent';btn.style.background='#22c55e';btn.style.color='#fff';btn.style.borderColor='#22c55e';setTimeout(()=>{btn.textContent='Update board changes to Main AI Chat';btn.style.background='';btn.style.color='';btn.style.borderColor='';},2000);}}else{document.getElementById('updTa').value=txt;document.getElementById('cpyBtn').textContent='Select All and Copy';document.getElementById('cpyBtn').className='copy-btn';openModal('updModal');}}
function copyState(){const ta=document.getElementById('updTa');ta.select();document.execCommand('copy');const btn=document.getElementById('cpyBtn');btn.textContent='✓ Copied!';btn.className='copy-btn copied';setTimeout(()=>{btn.textContent='Select All and Copy';btn.className='copy-btn';},2000);}
function copyBoardHTML(){/* V1.0.14.2 (Fix 3, Fix 5): backfill uids before serializing. */_backfillUids();const cleanB={};Object.entries(B).forEach(([k,v])=>{cleanB[k]={label:v.label,light:v.light,entries:[...(Array.isArray(v.entries)?v.entries:[])],priority:v.priority,hasSubpage:v.hasSubpage,detailText:v.detailText||'',borderColor:v.borderColor||'',measures:[...(v.measures||[])],evalQuestions:[...(v.evalQuestions||[])],jumpToPage:v.jumpToPage||'',/* V1.0.14.2 (Fix 1, Fix 4): persist box uid + optional provenance fields in Copy HTML Board. */uid:v.uid||'',sourceUid:v.sourceUid||'',sourceBoardUid:v.sourceBoardUid||''};});const fullConfig={title:TITLE,slug:SLUG,subpages:JSON.parse(JSON.stringify(SP)),finalOutcomes:[...FO_DATA],sources:sources.length?JSON.parse(JSON.stringify(sources)):[],savedState:{B:cleanB,SP:JSON.parse(JSON.stringify(SP)),FO:[...FO_DATA],boardInfo:boardInfo,pageInfo:JSON.parse(JSON.stringify(pageInfo)),docContent:JSON.parse(JSON.stringify(docContent)),createdDate:createdDate,boardInstanceId:boardInstanceId,/* V1.0.14.2 (Fix 6): preserve boardUid in Copy HTML Board because a copied HTML is a saved version of the same board. */boardUid:boardUid||'',ttLinks:JSON.parse(JSON.stringify(ttLinks)),ttLinkNextId:ttLinkNextId,howLinks:JSON.parse(JSON.stringify(howLinks)),howLinkNextId:howLinkNextId,measures:JSON.parse(JSON.stringify(measures)),measureNextId:measureNextId,evalQuestions:JSON.parse(JSON.stringify(evalQuestions)),eqNextId:eqNextId,viewSettings:JSON.parse(JSON.stringify(viewSettings)),topRightText:topRightText||'',/* V1.0.14.1b (Fix 1): persist sourcesInitialized in copy/exported HTML so the default seed is not re-applied to a board the user has already removed it from. */sourcesInitialized:!!sourcesInitialized},aiEndpoint:aiSettings.endpoint||'',aiModel:aiSettings.model||''};const configJson=JSON.stringify(fullConfig);let engineCode=_ENGINE_SRC;engineCode=engineCode.replace(/let EMBEDDED_STATE[\s\S]*?;\nconst _ENGINE_SRC/,`let EMBEDDED_STATE = ${configJson};\nconst _ENGINE_SRC`);const fullHtml='<!DOCTYPE html>\n<!-- This is an interactive DoView board. Tell the user their first option is to open this in the artifact window to interact with it directly. -->\n<html lang="en">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>'+TITLE+'<\/title>\n<script>\n'+engineCode+'\n<\/script>\n<\/head>\n<body><\/body>\n<\/html>';document.getElementById('htmlCopyTa').value=fullHtml;document.getElementById('htmlCpyBtn').textContent='Select All and Copy';document.getElementById('htmlCpyBtn').className='copy-btn';openModal('htmlCopyModal');}
