function openNewBoardModal(){var now=new Date();var y=now.getFullYear();var mo=String(now.getMonth()+1).padStart(2,'0');var d=String(now.getDate()).padStart(2,'0');var h=String(now.getHours()).padStart(2,'0');var mi=String(now.getMinutes()).padStart(2,'0');var fname='Untitled_'+y+'-'+mo+'-'+d+'_'+h+'-'+mi+'.html';var el=document.getElementById('newBoardFilename');if(el)el.value=fname;openModal('newBoardModal');}
function doCreateAndSaveNewBoard(){if(IS_READONLY){closeModal('newBoardModal');return;}var el=document.getElementById('newBoardFilename');var fname=el?el.value.trim():'';if(!fname){var now=new Date();var y=now.getFullYear();var mo=String(now.getMonth()+1).padStart(2,'0');var d=String(now.getDate()).padStart(2,'0');var h=String(now.getHours()).padStart(2,'0');var mi=String(now.getMinutes()).padStart(2,'0');fname='Untitled_'+y+'-'+mo+'-'+d+'_'+h+'-'+mi+'.html';}fname=fname.replace(/[\\\/:\*\?"<>\|]/g,'_');if(!/\.html$/i.test(fname))fname+='.html';resetToStarterBoard();downloadBoardWithFilename(fname);closeModal('newBoardModal');render();}
function resetToStarterBoard(){TITLE='Untitled DoView Board';SLUG='untitled_doview_board_'+Date.now().toString(36);SP=[{id:'p1',label:'This\u2013Then Page 1',pageType:'this_then',color:{bg:'#dbeafe',bdr:'#93c5fd',tab:'#3b82f6'},cols:[{h:'Stage 1',boxes:['New box']}]},{id:'p2',label:'How Page 1',pageType:'how',color:{bg:'#f1f5f9',bdr:'#cbd5e1',tab:'#64748b'},cols:[],howBoxes:[{id:'H001',label:'How (action, person, team, unit, organisation, capability, \u2026)'},{id:'H002',label:'How (action, person, team, unit, organisation, capability, \u2026)'},{id:'H003',label:'How (action, person, team, unit, organisation, capability, \u2026)'},{id:'H004',label:'How (action, person, team, unit, organisation, capability, \u2026)'},{id:'H005',label:'How (action, person, team, unit, organisation, capability, \u2026)'},{id:'H006',label:'How (action, person, team, unit, organisation, capability, \u2026)'},{id:'H007',label:'How (action, person, team, unit, organisation, capability, \u2026)'},{id:'H008',label:'How (action, person, team, unit, organisation, capability, \u2026)'}],nextHowNum:9,howLevel:1},{id:'p3',label:'Documentation Page 1',pageType:'documentation',color:{bg:'#f3e8ff',bdr:'#d8b4fe',tab:'#a855f8'},cols:[]}];B={};FO_DATA=[];boardInfo='';pageInfo={};docContent={};ttLinks=[];ttLinkNextId=1;howLinks=[];howLinkNextId=1;measures=[];measureNextId=1;evalQuestions=[];eqNextId=1;viewSettings=JSON.parse(JSON.stringify(DEFAULT_VIEW_SETTINGS));undoStack=[];inspectHome=null;inspectLinkedKeys=[];revealBox=null;revealType=null;sourceRefBox=null;openBox=null;editingType=null;currentPage='overview';docEditMode={};docEditBackup={};boardInstanceId='bi_'+Date.now()+'_'+Math.random().toString(36).slice(2,8);createdDate=new Date().toLocaleDateString('en-US',{year:'numeric',month:'long',day:'numeric'});buildInitialState();buildDepsMap();var hdr=document.getElementById('hdrTitle');if(hdr)hdr.textContent=TITLE;document.title=TITLE;var epw=document.getElementById('epWrap');if(epw)epw.style.display='none';try{Object.keys(localStorage).forEach(function(k){if(k.indexOf('doview-')===0&&k.indexOf('-v1')>0){/* clear other stale entries for this new slug only — leave other boards alone */}});}catch(e){}saveState();}
function downloadBoardWithFilename(fname){
  // V1.0.12.7 (Fix 9): mark save in progress for the "Create and Save New Empty Board" download path too.
  isSaving=true;updateSaveStateDisplay();
  /* V1.0.14.2 (Fix 3, Fix 5): backfill uids before serializing the new empty board. */_backfillUids();var cleanB={};Object.entries(B).forEach(function(entry){var k=entry[0],v=entry[1];cleanB[k]={label:v.label,light:v.light,entries:[].concat(v.entries||[]),priority:v.priority,hasSubpage:v.hasSubpage,detailText:v.detailText||'',borderColor:v.borderColor||'',measures:[].concat(v.measures||[]),evalQuestions:[].concat(v.evalQuestions||[]),jumpToPage:v.jumpToPage||'',/* V1.0.14.2 (Fix 1, Fix 4): persist box uid + optional provenance fields in Create and Save New Empty Board. */uid:v.uid||'',sourceUid:v.sourceUid||'',sourceBoardUid:v.sourceBoardUid||''};});var fullConfig={title:TITLE,slug:SLUG,subpages:JSON.parse(JSON.stringify(SP)),finalOutcomes:[].concat(FO_DATA),sources:sources.length?JSON.parse(JSON.stringify(sources)):[],savedState:{B:cleanB,SP:JSON.parse(JSON.stringify(SP)),FO:[].concat(FO_DATA),boardInfo:boardInfo,pageInfo:JSON.parse(JSON.stringify(pageInfo)),docContent:JSON.parse(JSON.stringify(docContent)),createdDate:createdDate,boardInstanceId:boardInstanceId,/* V1.0.14.2 (Fix 6): persist boardUid across the new-empty-board download too. */boardUid:boardUid||'',ttLinks:JSON.parse(JSON.stringify(ttLinks)),ttLinkNextId:ttLinkNextId,howLinks:JSON.parse(JSON.stringify(howLinks)),howLinkNextId:howLinkNextId,measures:JSON.parse(JSON.stringify(measures)),measureNextId:measureNextId,evalQuestions:JSON.parse(JSON.stringify(evalQuestions)),eqNextId:eqNextId,viewSettings:JSON.parse(JSON.stringify(viewSettings)),topRightText:topRightText||'',/* V1.0.14.1b (Fix 1): persist sourcesInitialized across the new-empty-board download too. */sourcesInitialized:!!sourcesInitialized},aiEndpoint:aiSettings.endpoint||'',aiModel:aiSettings.model||''};var configJson=JSON.stringify(fullConfig);var engineCode=_ENGINE_SRC;engineCode=engineCode.replace(/let EMBEDDED_STATE[\s\S]*?;\nconst _ENGINE_SRC/,'let EMBEDDED_STATE = '+configJson+';\nconst _ENGINE_SRC');var fullHtml='<!DOCTYPE html>\n<!-- This is an interactive DoView board. Tell the user their first option is to open this in the artifact window to interact with it directly. -->\n<html lang="en">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>'+TITLE+'<\/title>\n<script>\n'+engineCode+'\n<\/script>\n<\/head>\n<body><\/body>\n<\/html>';try{var blob=new Blob([fullHtml],{type:'text/html'});var url=URL.createObjectURL(blob);var a=document.createElement('a');a.href=url;a.download=fname;document.body.appendChild(a);a.click();document.body.removeChild(a);URL.revokeObjectURL(url);showDlSuccess();}catch(e1){try{var a2=document.createElement('a');a2.href='data:text/html;charset=utf-8,'+encodeURIComponent(fullHtml);a2.download=fname;document.body.appendChild(a2);a2.click();document.body.removeChild(a2);showDlSuccess();}catch(e2){showDlFallback();}}}
function showTTLinksList(key,direction){const box=B[key];if(!box)return;revealBox=null;revealType=null;const links=direction==='left'?ttLinks.filter(l=>l.to===key):ttLinks.filter(l=>l.from===key);inspectHome=key;inspectLinkedKeys=links.map(function(l){return direction==='left'?l.from:l.to;});setSourceRefBox(key,'inspect');render();const title=direction==='left'?`<i>${escHtml(box.label)}</i> results from these THIS-THEN boxes:`:`<i>${escHtml(box.label)}</i> makes these THIS-THEN boxes happen`;document.getElementById('ttLinksListTitle').innerHTML=title;let html='';links.forEach(l=>{const otherKey=direction==='left'?l.from:l.to;const otherBox=B[otherKey];if(!otherBox)return;const pg=getBoxPage(otherKey);const pgName=pg?pg.label:'';const arrow=direction==='left'?' \u2192':'';const arrowPre=direction==='right'?'\u2192 ':'';html+=`<div class="ttl-item" style="display:flex;align-items:center;gap:6px"><div style="flex:1;cursor:pointer" onclick="closeModal('ttLinksListModal');inspectNavTo('${otherKey}')"><div class="ttl-item-title">${arrowPre}${otherBox.label}${arrow}</div><div class="ttl-item-page">${pgName}</div></div><span class="link-info-btn" onclick="event.stopPropagation();closeModal('ttLinksListModal');openLinkDetail('${l.id}')" title="Link details">\u2139</span></div>`;});html+='<div style="margin-top:8px;padding-top:6px;border-top:1px solid var(--bdr)">'+buildTTLinkPopupPicker(key,direction)+'</div>';document.getElementById('ttLinksListContent').innerHTML=html;document.getElementById('ttLinksListBtns').innerHTML='<button class="modal-close" onclick="addTTLinkFromPopup(\''+key+'\',\''+direction+'\')">Add</button><button class="modal-close" style="background:var(--text2)" onclick="closeModal(\'ttLinksListModal\')">Cancel</button>';openModal('ttLinksListModal');}
function buildTTLinkPopupPicker(key,direction){let opts='<option value="">Select a target\u2026</option>';SP.forEach(sp=>{if((sp.pageType||'this_then')!=='this_then')return;let boxOpts='';sp.cols.forEach((col,ci)=>{col.boxes.forEach((_,bi)=>{const k=sp.id+'-c'+ci+'-b'+bi;if(k===key)return;const b=B[k];if(!b)return;const existsAsFrom=ttLinks.some(l=>l.from===key&&l.to===k);const existsAsTo=ttLinks.some(l=>l.from===k&&l.to===key);if(direction==='right'&&existsAsFrom)return;if(direction==='left'&&existsAsTo)return;boxOpts+='<option value="'+k+'">'+b.label+'</option>';});});if(boxOpts)opts+='<optgroup label="'+sp.label+'">'+boxOpts+'</optgroup>';});return '<div style="margin-top:8px"><select class="how-link-sel" id="ttPopupPicker" style="width:100%">'+opts+'</select></div>';}function addTTLinkFromPopup(key,direction){const sel=document.getElementById('ttPopupPicker');if(!sel||!sel.value)return;if(direction==='right')addTTLink(key,sel.value);else addTTLink(sel.value,key);closeModal('ttLinksListModal');}
function navToBox(key){const fm=key.match(/^final-b(\d+)$/);if(fm){if(currentPage!=='final')navTo('final');setTimeout(()=>{openBox=key;render();const el=document.getElementById('bx-'+key);if(el)el.scrollIntoView({behavior:'smooth',block:'center'});},100);return;}const m=key.match(/^(p\d+)/);if(m){const pid=m[1];if(currentPage!==pid)navTo(pid);setTimeout(()=>{openBox=key;render();const el=document.getElementById('bx-'+key);if(el)el.scrollIntoView({behavior:'smooth',block:'center'});},100);}else{openBox=key;render();}}
function cleanupTTLinks(){ttLinks=ttLinks.filter(l=>B[l.from]&&B[l.to]&&isTTBox(l.from)&&isTTBox(l.to));}
function isHowBox(key){const m=key.match(/^(p\d+)-(H\d+)$/);if(!m)return false;const sp=SP.find(s=>s.id===m[1]);return sp&&sp.pageType==='how';}
function buildHowActingOnSection(key){if(!isTTBox(key))return '';const box=B[key];if(!box)return '';const links=howLinks.filter(l=>l.to===key);let rows='';links.forEach(l=>{const fromBox=B[l.from];if(!fromBox)return;const pg=getBoxPage(l.from);const pgName=pg?pg.label:'';const hm=l.from.match(/^(p\d+)-(H\d+)$/);const hId=hm?hm[2]:'';rows+='<div class="how-link-row"><span class="how-link-box" title="'+fromBox.label+'">'+fromBox.label+'</span><span class="how-link-pg">('+pgName+(hId?' '+hId:'')+')</span><span class="link-info-btn" onclick="event.stopPropagation();openLinkDetail(\''+l.id+'\')" title="Link details">\u2139</span><span class="how-link-rm" onclick="removeHowLink(\''+l.id+'\')">&#x2715;</span></div>';});const picker=buildHowActingOnPicker(key);return '<div class="how-link-section"><div class="how-link-hdr">How boxes linking to this box</div>'+(rows||'<div style="font-size:10.5px;color:var(--text2);margin-bottom:6px;font-style:italic">No links yet</div>')+picker+'</div>';}
function buildHowActingOnPicker(ttKey){let opts='<option value="">Select a How box\u2026</option>';SP.forEach(sp=>{if(sp.pageType!=='how'||!sp.howBoxes)return;let boxOpts='';sp.howBoxes.forEach(hb=>{const k=sp.id+'-'+hb.id;const b=B[k];if(!b)return;boxOpts+='<option value="'+k+'">'+hb.id+' \u2014 '+b.label+'</option>';});if(boxOpts)opts+='<optgroup label="'+sp.label+'">'+boxOpts+'</optgroup>';});return '<div class="how-link-add"><select class="how-link-sel" id="howActingOnPicker">'+opts+'</select><button class="how-link-abtn" onclick="addHowActingOnFromPicker(\''+ttKey+'\')">Add</button></div>';}
function addHowActingOnFromPicker(ttKey){const sel=document.getElementById('howActingOnPicker');if(!sel||!sel.value)return;addHowLink(sel.value,ttKey);}
function buildHowLinksSection(key){if(!isHowBox(key))return '';const box=B[key];if(!box)return '';const links=howLinks.filter(l=>l.from===key);let ttRows='',howRows='';links.forEach(l=>{const targetBox=B[l.to];if(!targetBox)return;const targetPage=getBoxPage(l.to);const pageName=targetPage?targetPage.label:'';if(isTTBox(l.to)){ttRows+=`<div class="how-link-row"><span class="how-link-box" title="${targetBox.label}">${targetBox.label}</span><span class="how-link-pg">(${pageName})</span><span class="link-info-btn" onclick="event.stopPropagation();openLinkDetail('${l.id}')" title="Link details">\u2139</span><span class="how-link-rm" onclick="removeHowLink('${l.id}')">\u2715</span></div>`;}else if(isHowBox(l.to)){const hm=l.to.match(/^(p\d+)-(H\d+)$/);const hId=hm?hm[2]:'';howRows+=`<div class="how-link-row"><span class="how-link-box" title="${targetBox.label}">${targetBox.label}</span><span class="how-link-pg">(${pageName} ${hId})</span><span class="link-info-btn" onclick="event.stopPropagation();openLinkDetail('${l.id}')" title="Link details">\u2139</span><span class="how-link-rm" onclick="removeHowLink('${l.id}')">\u2715</span></div>`;}});const ttPicker=buildHowLinkTTPicker(key);const howPicker=buildHowLinkHowPicker(key);return `<div class="how-link-section"><div class="how-link-hdr">Link upward to a This\u2013Then box</div>${ttRows||'<div style="font-size:10.5px;color:var(--text2);margin-bottom:6px;font-style:italic">No links yet</div>'}${ttPicker}<div class="how-link-hdr" style="margin-top:10px">Link to another How box (upward or non-up-and-down)</div>${howRows||'<div style="font-size:10.5px;color:var(--text2);margin-bottom:6px;font-style:italic">No links yet</div>'}${howPicker}</div>`;}
function buildHowLinkTTPicker(key){let opts='<option value="">Select a This\u2013Then box\u2026</option>';SP.forEach(sp=>{if((sp.pageType||'this_then')!=='this_then')return;let boxOpts='';sp.cols.forEach((col,ci)=>{col.boxes.forEach((_,bi)=>{const k=`${sp.id}-c${ci}-b${bi}`;const b=B[k];if(!b)return;boxOpts+=`<option value="${k}">${b.label}</option>`;});});if(boxOpts)opts+=`<optgroup label="${sp.label}">${boxOpts}</optgroup>`;});return `<div class="how-link-add"><select class="how-link-sel" id="howLinkTTPicker">${opts}</select><button class="how-link-abtn" onclick="addHowLinkFromTTPicker('${key}')">Add</button></div>`;}
function buildHowLinkHowPicker(key){const fromPage=getBoxPage(key);let opts='<option value="">Select a How box\u2026</option>';SP.forEach(sp=>{if(sp.pageType!=='how'||!sp.howBoxes)return;let boxOpts='';sp.howBoxes.forEach(hb=>{const k=`${sp.id}-${hb.id}`;if(k===key)return;const b=B[k];if(!b)return;boxOpts+=`<option value="${k}">${hb.id} \u2014 ${b.label}</option>`;});if(boxOpts)opts+=`<optgroup label="${sp.label}">${boxOpts}</optgroup>`;});return `<div class="how-link-add"><select class="how-link-sel" id="howLinkHowPicker">${opts}</select><button class="how-link-abtn" onclick="addHowLinkFromHowPicker('${key}')">Add</button></div>`;}
function addHowLinkFromTTPicker(fromKey){const sel=document.getElementById('howLinkTTPicker');if(!sel||!sel.value)return;addHowLink(fromKey,sel.value);}
function addHowLinkFromHowPicker(fromKey){const sel=document.getElementById('howLinkHowPicker');if(!sel||!sel.value)return;addHowLink(fromKey,sel.value);}
function addHowLink(from,to){if(IS_READONLY)return;if(!isHowBox(from))return;if(!isTTBox(to)&&!isHowBox(to))return;if(from===to)return;const exists=howLinks.some(l=>l.from===from&&l.to===to);if(exists)return;takeSnapshot();/* V1.0.14.2 (Fix 5): assign stable uid to the newly created How link. */howLinks.push({id:'hwl_'+howLinkNextId++,from,to,mainText:'',notes1:'',notes2:'',notes3:'',uid:_genUid('link')});saveState();render();}
function removeHowLink(id){if(IS_READONLY)return;const idx=howLinks.findIndex(l=>l.id===id);if(idx<0)return;takeSnapshot();howLinks.splice(idx,1);saveState();render();}
function cleanupHowLinks(){howLinks=howLinks.filter(l=>B[l.from]&&B[l.to]&&isHowBox(l.from)&&(isTTBox(l.to)||isHowBox(l.to)));}

function getViewForPage(pid){const sp=SP.find(s=>s.id===pid);if(!sp)return null;const pt=sp.pageType||'this_then';if(pt==='this_then')return viewSettings.thisThen;if(pt==='how')return viewSettings.how;return null;}

function openViewPanel(){const pid=currentPage;let pt,vs;if(pid==='final'){pt='finalOutcomes';vs=viewSettings.finalOutcomes;}else{const sp=SP.find(s=>s.id===pid);if(!sp)return;pt=sp.pageType||'this_then';vs=pt==='this_then'?viewSettings.thisThen:pt==='how'?viewSettings.how:null;}if(!vs)return;const title=pt==='this_then'?'View settings \u2014 This\u2013Then Pages':pt==='how'?'View settings \u2014 How Pages':'View settings \u2014 Final Outcomes';document.getElementById('viewPanelTitle').textContent=title;let html='';if(pt==='this_then'){/* V1.0.12.9a (Fix 1): TT-page non-up-and-down toggle now reads "Show non-up-and-down links to How boxes"; the up-and-down toggle on TT pages now reads "Show up-and-down links to How boxes". Ordinary TT\u2192TT links belong to the normal This\u2013Then link system above. */html+=vChk('vShowTrafficLights','Show traffic lights',vs.showTrafficLights);html+=vChk('vShowPriorities','Show priorities',vs.showPriorities);html+=vChk('vShowMainText','Show main text under boxes',vs.showMainText);html+=vChk('vShowMeasures','Show measures under boxes',vs.showMeasures);html+=vChk('vShowEvalQuestions','Show evaluation questions under boxes',vs.showEvalQuestions);html+=vChk('vShowCounts','Show This\u2013Then link counts (just between boxes on This\u2013Then pages)',vs.showCounts);html+=vChk('vShowHowCounts','Show up-and-down links to How boxes',vs.showHowCounts);html+=vChk('vShowLateralHow','Show non-up-and-down links to How boxes',vs.showLateralHow===true);}else if(pt==='how'){/* V1.0.12.9a (Fix 1): exact user-facing View wording for How pages \u2014 ordinary TT\u2192TT links stay under the normal This\u2013Then link system; the non-up-and-down category here covers non-up-and-down links to This\u2013Then and How boxes. */html+=vChk('vShowTrafficLights','Show traffic lights',vs.showTrafficLights);html+=vChk('vShowPriorities','Show priorities',vs.showPriorities);html+=vChk('vShowMainText','Show main text under boxes',vs.showMainText);html+=vChk('vShowNumbering','Show numbering',vs.showNumbering);html+=vChk('vShowMeasures','Show measures under boxes',vs.showMeasures);html+=vChk('vShowEvalQuestions','Show evaluation questions under boxes',vs.showEvalQuestions);html+=vChk('vShowWhyCounts','Show up-and-down links to This\u2013Then and How boxes',vs.showWhyCounts);html+=vChk('vShowLateralHow','Show non-up-and-down links to This\u2013Then and How boxes',vs.showLateralHow===true);}else if(pt==='finalOutcomes'){html+=vChk('vShowTrafficLights','Show traffic lights',vs.showTrafficLights);html+=vChk('vShowPriorities','Show priorities',vs.showPriorities);html+=vChk('vShowMainText','Show main text under boxes',vs.showMainText);html+=vChk('vShowMeasures','Show measures under boxes',vs.showMeasures);html+=vChk('vShowEvalQuestions','Show evaluation questions under boxes',vs.showEvalQuestions);}
// V1.0.12.3 (Fix 6): Clear All / Restore Defaults controls sit below the toggles.
// V1.0.12.8 (Fix 6): Final Outcomes pages now also get the Clear All / Restore Defaults buttons so the default view
// (traffic lights on, priorities on; all other optional items off) can be re-applied from this panel, bringing Final
// Outcomes into line with the other page types. clearAllViewForCurrentPage and restoreDefaultsForCurrentPage already
// have finalOutcomes branches; the only change here is rendering the button row for this page type too.
if(pt==='this_then'||pt==='how'||pt==='finalOutcomes'){html+='<div class="view-panel-btnrow"><button class="view-panel-btn" onclick="clearAllViewForCurrentPage()">Clear All</button><button class="view-panel-btn" onclick="restoreDefaultsForCurrentPage()">Restore Defaults</button></div>';}
document.getElementById('viewPanelBody').innerHTML=html;openModal('viewPanelModal');}
function vChk(id,label,checked){return '<div class="view-chk"><input type="checkbox" id="'+id+'"'+(checked?' checked':'')+' /><label for="'+id+'">'+label+'</label></div>';}
function saveViewPanel(){/* V1.0.12.9c (Fix 2): in read-only mode this function now runs normally. Changing View is a display/viewing change, not a content edit \u2014 so it should be allowed even in read-only mode. saveState() is a no-op in read-only mode so the choice does not persist to localStorage past this session, which is acceptable behaviour for a view toggle. */const pid=currentPage;if(pid==='final'){viewSettings.finalOutcomes.showTrafficLights=!!gEl('vShowTrafficLights').checked;viewSettings.finalOutcomes.showPriorities=!!gEl('vShowPriorities').checked;viewSettings.finalOutcomes.showMeasures=!!gEl('vShowMeasures').checked;viewSettings.finalOutcomes.showEvalQuestions=!!gEl('vShowEvalQuestions').checked;viewSettings.finalOutcomes.showMainText=!!gEl('vShowMainText').checked;}else{const sp=SP.find(s=>s.id===pid);if(!sp){closeModal('viewPanelModal');return;}const pt=sp.pageType||'this_then';if(pt==='this_then'){viewSettings.thisThen.showCounts=!!gEl('vShowCounts').checked;viewSettings.thisThen.showTrafficLights=!!gEl('vShowTrafficLights').checked;viewSettings.thisThen.showPriorities=!!gEl('vShowPriorities').checked;viewSettings.thisThen.showHowCounts=!!gEl('vShowHowCounts').checked;viewSettings.thisThen.showMeasures=!!gEl('vShowMeasures').checked;viewSettings.thisThen.showEvalQuestions=!!gEl('vShowEvalQuestions').checked;viewSettings.thisThen.showMainText=!!gEl('vShowMainText').checked;viewSettings.thisThen.showLateralHow=!!gEl('vShowLateralHow').checked;}else if(pt==='how'){viewSettings.how.showNumbering=!!gEl('vShowNumbering').checked;viewSettings.how.showTrafficLights=!!gEl('vShowTrafficLights').checked;viewSettings.how.showPriorities=!!gEl('vShowPriorities').checked;viewSettings.how.showWhyCounts=!!gEl('vShowWhyCounts').checked;viewSettings.how.showLateralHow=!!gEl('vShowLateralHow').checked;viewSettings.how.showMeasures=!!gEl('vShowMeasures').checked;viewSettings.how.showEvalQuestions=!!gEl('vShowEvalQuestions').checked;viewSettings.how.showMainText=!!gEl('vShowMainText').checked;}}saveState();closeModal('viewPanelModal');render();}
// V1.0.12.3 (Fix 6): Clear All turns off all toggles in the current page's View list.
function clearAllViewForCurrentPage(){const pid=currentPage;let pt;if(pid==='final'){pt='finalOutcomes';}else{const sp=SP.find(s=>s.id===pid);if(!sp)return;pt=sp.pageType||'this_then';}if(pt==='this_then'){Object.keys(viewSettings.thisThen).forEach(k=>{viewSettings.thisThen[k]=false;});}else if(pt==='how'){Object.keys(viewSettings.how).forEach(k=>{viewSettings.how[k]=false;});}else if(pt==='finalOutcomes'){Object.keys(viewSettings.finalOutcomes).forEach(k=>{viewSettings.finalOutcomes[k]=false;});}saveState();openViewPanel();render();}
// V1.0.12.3 (Fix 6 + 1.0.12.3a): Restore Defaults re-applies the built-in defaults for this page type.
function restoreDefaultsForCurrentPage(){const pid=currentPage;let pt;if(pid==='final'){pt='finalOutcomes';}else{const sp=SP.find(s=>s.id===pid);if(!sp)return;pt=sp.pageType||'this_then';}if(pt==='this_then'){viewSettings.thisThen=JSON.parse(JSON.stringify(DEFAULT_VIEW_SETTINGS.thisThen));}else if(pt==='how'){viewSettings.how=JSON.parse(JSON.stringify(DEFAULT_VIEW_SETTINGS.how));}else if(pt==='finalOutcomes'){viewSettings.finalOutcomes=JSON.parse(JSON.stringify(DEFAULT_VIEW_SETTINGS.finalOutcomes));}saveState();openViewPanel();render();}
function gEl(id){return document.getElementById(id);}


// ─── HOW LINK LEVEL CLASSIFICATION (V1.0.12.3) — strict adjacency ───
// FIX 1: only adjacent How-levels are hierarchical, and only Level-1 How→This–Then counts as hierarchical.
//        Anything else (same-level, skipped-level, Level-2+→TT, no-level) is lateral.
function getHowPageLevel(key){const m=key.match(/^(p\d+)/);if(!m)return null;const sp=SP.find(s=>s.id===m[1]);if(!sp||sp.pageType!=='how')return null;return sp.howLevel||null;}
function classifyHowLink(fromKey,toKey){
  if(isTTBox(toKey)){
    // Only Level-1 How boxes may hierarchically link to This–Then boxes.
    const fromLvl=getHowPageLevel(fromKey);
    if(fromLvl===1)return 'upward';
    return 'lateral';
  }
  if(!isHowBox(toKey))return 'lateral';
  const fromLvl=getHowPageLevel(fromKey);const toLvl=getHowPageLevel(toKey);
  if(fromLvl===null||fromLvl===undefined||toLvl===null||toLvl===undefined)return 'lateral';
  if(isSamePageHow(fromKey,toKey))return 'lateral';
  // Strict adjacency — only ±1 level counts as hierarchical.
  if(toLvl===fromLvl-1)return 'upward';
  if(toLvl===fromLvl+1)return 'downward';
  return 'lateral';
}
function getUpwardHowCount(key){return howLinks.filter(l=>l.from===key&&classifyHowLink(l.from,l.to)==='upward').length;}
// V1.0.12.4 (Fix 2): bottom (downward) affordance on a How box now counts ALL hierarchical links
// connecting this box with the adjacent-lower level — outgoing downward AND incoming upward from below.
// This keeps counts consistent on both source and target sides of any hierarchical link.
function getDownwardHowCount(key){return howLinks.filter(l=>(l.from===key&&classifyHowLink(l.from,l.to)==='downward')||(l.to===key&&classifyHowLink(l.from,l.to)==='upward')).length;}
function getLateralHowCount(key){return howLinks.filter(l=>(l.from===key||l.to===key)&&classifyHowLink(l.from,l.to)==='lateral').length;}
function showDownwardHowList(key){const box=B[key];if(!box)return;revealBox=null;revealType=null;/* V1.0.12.4 (Fix 2): include both outgoing downward links from this box AND incoming upward links from the adjacent lower level, so a hierarchical link appears in the popup from either end. */const links=howLinks.filter(l=>(l.from===key&&classifyHowLink(l.from,l.to)==='downward')||(l.to===key&&classifyHowLink(l.from,l.to)==='upward'));inspectHome=key;inspectLinkedKeys=links.map(l=>l.from===key?l.to:l.from);setSourceRefBox(key,'inspect');render();document.getElementById('howCountListTitle').innerHTML='<i>'+escHtml(box.label)+'</i> up-and-down links with adjacent lower-level boxes:';let html='';links.forEach(l=>{const otherKey=l.from===key?l.to:l.from;const otherBox=B[otherKey];if(!otherBox)return;const pg=getBoxPage(otherKey);const pgName=pg?pg.label:'';const hm=otherKey.match(/^(p\d+)-(H\d+)$/);const hId=hm?hm[2]:'';html+='<div class="ttl-item" style="display:flex;align-items:center;gap:6px"><div style="flex:1;cursor:pointer" onclick="closeModal(\'howCountListModal\');inspectNavTo(\''+otherKey+'\')"><div class="ttl-item-title">'+otherBox.label+'</div><div class="ttl-item-page">'+pgName+(hId?' '+hId:'')+'</div></div><span class="link-info-btn" onclick="event.stopPropagation();closeModal(\'howCountListModal\');openLinkDetail(\''+l.id+'\')">\u2139</span><button class="tt-link-abtn" style="margin-left:4px;font-size:9px" onclick="event.stopPropagation();removeHowLink(\''+l.id+'\');closeModal(\'howCountListModal\')">\u2715</button></div>';});html+='<div style="margin-top:8px;padding-top:6px;border-top:1px solid var(--bdr)">'+buildDownwardHowPopupPicker(key)+'</div>';document.getElementById('howCountListContent').innerHTML=html||'<div style="color:var(--text2);font-style:italic">No up-and-down links with lower-level boxes</div><div style="margin-top:8px">'+buildDownwardHowPopupPicker(key)+'</div>';document.getElementById('howCountListBtns').innerHTML='<button class="modal-close" onclick="addHowLinkFromPopupPicker(\''+key+'\',\'dnHowPopupPicker\')">Add</button><button class="modal-close" style="background:var(--text2)" onclick="closeModal(\'howCountListModal\')">Cancel</button>';openModal('howCountListModal');}
function showLateralHowList(key){const box=B[key];if(!box)return;revealBox=null;revealType=null;const links=howLinks.filter(l=>(l.from===key||l.to===key)&&classifyHowLink(l.from,l.to)==='lateral');inspectHome=key;inspectLinkedKeys=links.map(l=>l.from===key?l.to:l.from);setSourceRefBox(key,'inspect');render();document.getElementById('howCountListTitle').innerHTML='<i>'+escHtml(box.label)+'</i> non-up-and-down How links:';let html='';links.forEach(l=>{const otherKey=l.from===key?l.to:l.from;const otherBox=B[otherKey];if(!otherBox)return;const pg=getBoxPage(otherKey);const pgName=pg?pg.label:'';const hm=otherKey.match(/^(p\d+)-(H\d+)$/);const hId=hm?hm[2]:'';html+='<div class="ttl-item" style="display:flex;align-items:center;gap:6px"><div style="flex:1;cursor:pointer" onclick="closeModal(\'howCountListModal\');inspectNavTo(\''+otherKey+'\')"><div class="ttl-item-title">'+otherBox.label+'</div><div class="ttl-item-page">'+pgName+(hId?' '+hId:'')+'</div></div><span class="link-info-btn" onclick="event.stopPropagation();closeModal(\'howCountListModal\');openLinkDetail(\''+l.id+'\')">\u2139</span><button class="tt-link-abtn" style="margin-left:4px;font-size:9px" onclick="event.stopPropagation();removeHowLink(\''+l.id+'\');closeModal(\'howCountListModal\')">\u2715</button></div>';});html+='<div style="margin-top:8px;padding-top:6px;border-top:1px solid var(--bdr)">'+buildLateralHowPopupPicker(key)+'</div>';document.getElementById('howCountListContent').innerHTML=html||'<div style="color:var(--text2);font-style:italic">No non-up-and-down links</div><div style="margin-top:8px">'+buildLateralHowPopupPicker(key)+'</div>';document.getElementById('howCountListBtns').innerHTML='<button class="modal-close" onclick="addHowLinkFromPopupPicker(\''+key+'\',\'latHowPopupPicker\')">Add</button><button class="modal-close" style="background:var(--text2)" onclick="closeModal(\'howCountListModal\')">Cancel</button>';openModal('howCountListModal');}
function buildDownwardHowPopupPicker(key){const fromSp=getBoxPage(key);const fromLvl=fromSp&&fromSp.howLevel?fromSp.howLevel:null;let opts='<option value="">Select a target\u2026</option>';SP.forEach(sp=>{if(sp.pageType!=='how'||!sp.howBoxes)return;if(fromLvl===null||fromLvl===undefined)return;if(sp.howLevel!==fromLvl+1)return;let boxOpts='';sp.howBoxes.forEach(hb=>{const k=sp.id+'-'+hb.id;if(k===key)return;const b=B[k];if(!b)return;if(howLinks.some(l=>l.from===key&&l.to===k))return;boxOpts+='<option value="'+k+'">'+hb.id+' \u2014 '+b.label+'</option>';});if(boxOpts)opts+='<optgroup label="'+sp.label+'">'+boxOpts+'</optgroup>';});return '<div style="margin-top:8px"><select class="how-link-sel" id="dnHowPopupPicker" style="width:100%">'+opts+'</select></div>';}
function buildLateralHowPopupPicker(key){const fromSp=getBoxPage(key);const fromLvl=fromSp&&fromSp.howLevel?fromSp.howLevel:null;let opts='<option value="">Select a target\u2026</option>';SP.forEach(sp=>{if(sp.pageType==='how'&&sp.howBoxes){const spLvl=sp.howLevel;if(fromLvl!==null&&fromLvl!==undefined&&spLvl!==null&&spLvl!==undefined){if(spLvl===fromLvl-1||spLvl===fromLvl+1)return;}let boxOpts='';sp.howBoxes.forEach(hb=>{const k=sp.id+'-'+hb.id;if(k===key)return;const b=B[k];if(!b)return;if(howLinks.some(l=>(l.from===key&&l.to===k)||(l.from===k&&l.to===key)))return;boxOpts+='<option value="'+k+'">'+hb.id+' \u2014 '+b.label+'</option>';});if(boxOpts)opts+='<optgroup label="'+sp.label+'">'+boxOpts+'</optgroup>';}else if((sp.pageType||'this_then')==='this_then'){/* V1.0.12.3 (Fix 1): only Level-2+ How boxes can lateral-link to This\u2013Then boxes (L1\u2192TT is hierarchical, handled via upward picker) */if(fromLvl===null||fromLvl===undefined||fromLvl===1)return;let boxOpts='';sp.cols.forEach((col,ci)=>{col.boxes.forEach((_,bi)=>{const k=sp.id+'-c'+ci+'-b'+bi;const b=B[k];if(!b)return;if(howLinks.some(l=>l.from===key&&l.to===k))return;boxOpts+='<option value="'+k+'">'+b.label+'</option>';});});if(boxOpts)opts+='<optgroup label="'+sp.label+' (This\u2013Then)">'+boxOpts+'</optgroup>';}});return '<div style="margin-top:8px"><select class="how-link-sel" id="latHowPopupPicker" style="width:100%">'+opts+'</select></div>';}
function addHowLinkFromPopupPicker(fromKey,pickerId){const sel=document.getElementById(pickerId);if(!sel||!sel.value)return;addHowLink(fromKey,sel.value);closeModal('howCountListModal');}

function getHowCountForTTBox(key){return howLinks.filter(l=>l.to===key&&classifyHowLink(l.from,l.to)==='upward').length;}
// V1.0.12.3 (Fix 1): count of lateral How links pointing at a This–Then box.
function getLateralHowCountForTTBox(key){return howLinks.filter(l=>l.to===key&&classifyHowLink(l.from,l.to)==='lateral').length;}
// V1.0.12.4 (Fix 2): top (upward) affordance on a How box now counts ALL hierarchical links
// connecting this box with the adjacent-higher level — outgoing upward AND incoming downward from above.
function getWhyCountForHowBox(key){return howLinks.filter(l=>(l.from===key&&classifyHowLink(l.from,l.to)==='upward')||(l.to===key&&classifyHowLink(l.from,l.to)==='downward')).length;}
function getHowToHowInCount(key){return howLinks.filter(l=>l.to===key&&isHowBox(l.from)&&!isSamePageHow(l.from,l.to)).length;}
