function buildHowActingOnPopupPicker2(ttKey){let opts='<option value="">Select a Level-1 How box\u2026</option>';SP.forEach(sp=>{if(sp.pageType!=='how'||!sp.howBoxes)return;if(sp.howLevel!==1)return;/* V1.0.12.3 (Fix 1): only Level-1 How boxes may hierarchically link to This\u2013Then boxes */let boxOpts='';sp.howBoxes.forEach(hb=>{const k=sp.id+'-'+hb.id;const b=B[k];if(!b)return;if(howLinks.some(l=>l.from===k&&l.to===ttKey))return;boxOpts+='<option value="'+k+'">'+hb.id+' \u2014 '+b.label+'</option>';});if(boxOpts)opts+='<optgroup label="'+sp.label+'">'+boxOpts+'</optgroup>';});return '<div style="margin-top:8px"><select class="how-link-sel" id="howPopup2Picker" style="width:100%">'+opts+'</select></div>';}function addHowFromPopup2(ttKey){const sel=document.getElementById('howPopup2Picker');if(!sel||!sel.value)return;addHowLink(sel.value,ttKey);closeModal('howCountListModal');}

function showHowCountList(key){const box=B[key];if(!box)return;revealBox=null;revealType=null;const links=howLinks.filter(l=>l.to===key&&classifyHowLink(l.from,l.to)==='upward');inspectHome=key;inspectLinkedKeys=links.map(function(l){return l.from;});setSourceRefBox(key,'inspect');render();document.getElementById('howCountListTitle').innerHTML='<i>'+escHtml(box.label)+'</i> is acted on by these Level-1 HOW boxes:';let html='';links.forEach(l=>{const fromBox=B[l.from];if(!fromBox)return;const pg=getBoxPage(l.from);const pgName=pg?pg.label:'';const hm=l.from.match(/^(p\d+)-(H\d+)$/);const hId=hm?hm[2]:'';html+='<div class="ttl-item" style="display:flex;align-items:center;gap:6px"><div style="flex:1;cursor:pointer" onclick="closeModal(\'howCountListModal\');inspectNavTo(\''+l.from+'\')"><div class="ttl-item-title">'+fromBox.label+' \u2191</div><div class="ttl-item-page">'+pgName+(hId?' '+hId:'')+'</div></div><span class="link-info-btn" onclick="event.stopPropagation();closeModal(\'howCountListModal\');openLinkDetail(\''+l.id+'\')" title="Link details">\u2139</span></div>';});html+='<div style="margin-top:8px;padding-top:6px;border-top:1px solid var(--bdr)">'+buildHowActingOnPopupPicker2(key)+'</div>';document.getElementById('howCountListContent').innerHTML=html||'<div style="color:var(--text2);font-style:italic">No hierarchical How links</div><div style="margin-top:8px">'+buildHowActingOnPopupPicker2(key)+'</div>';document.getElementById('howCountListBtns').innerHTML='<button class="modal-close" onclick="addHowFromPopup2(\''+key+'\')">Add</button><button class="modal-close" style="background:var(--text2)" onclick="closeModal(\'howCountListModal\')">Cancel</button>';openModal('howCountListModal');}

function showWhyCountList(key){const box=B[key];if(!box)return;revealBox=null;revealType=null;/* V1.0.12.4 (Fix 2): include both outgoing upward links from this box AND incoming downward links from the adjacent higher level, so a hierarchical link appears in the popup from either end. */const links=howLinks.filter(l=>(l.from===key&&classifyHowLink(l.from,l.to)==='upward')||(l.to===key&&classifyHowLink(l.from,l.to)==='downward'));inspectHome=key;inspectLinkedKeys=links.map(function(l){return l.from===key?l.to:l.from;});setSourceRefBox(key,'inspect');render();document.getElementById('howCountListTitle').innerHTML='<i>'+escHtml(box.label)+'</i> up-and-down links with adjacent higher-level boxes:';let html='';links.forEach(l=>{const otherKey=l.from===key?l.to:l.from;const otherBox=B[otherKey];if(!otherBox)return;const pg=getBoxPage(otherKey);const pgName=pg?pg.label:'';const hm=otherKey.match(/^(p\d+)-(H\d+)$/);const hId=hm?hm[2]:'';html+='<div class="ttl-item" style="display:flex;align-items:center;gap:6px"><div style="flex:1;cursor:pointer" onclick="closeModal(\'howCountListModal\');inspectNavTo(\''+otherKey+'\')"><div class="ttl-item-title">'+otherBox.label+'</div><div class="ttl-item-page">'+pgName+(hId?' '+hId:'')+'</div></div><span class="link-info-btn" onclick="event.stopPropagation();closeModal(\'howCountListModal\');openLinkDetail(\''+l.id+'\')" title="Link details">\u2139</span><button class="tt-link-abtn" style="margin-left:4px;font-size:9px" onclick="event.stopPropagation();removeHowLink(\''+l.id+'\');closeModal(\'howCountListModal\')">\u2715</button></div>';});html+='<div style="margin-top:8px;padding-top:6px;border-top:1px solid var(--bdr)">'+buildUpwardHowPopupPicker(key)+'</div>';document.getElementById('howCountListContent').innerHTML=html||'<div style="color:var(--text2);font-style:italic">No up-and-down links with higher-level boxes</div><div style="margin-top:8px">'+buildUpwardHowPopupPicker(key)+'</div>';document.getElementById('howCountListBtns').innerHTML='<button class="modal-close" onclick="addHowLinkFromPopupPicker(\''+key+'\',\'upHowPopupPicker\')">Add</button><button class="modal-close" style="background:var(--text2)" onclick="closeModal(\'howCountListModal\')">Cancel</button>';openModal('howCountListModal');}

function buildUpwardHowPopupPicker(key){const fromSp=getBoxPage(key);const fromLvl=fromSp&&fromSp.howLevel?fromSp.howLevel:null;let opts='<option value="">Select a target\u2026</option>';SP.forEach(sp=>{if(sp.pageType==='how'&&sp.howBoxes){if(fromLvl===null||fromLvl===undefined)return;if(sp.howLevel!==fromLvl-1)return;let boxOpts='';sp.howBoxes.forEach(hb=>{const k=sp.id+'-'+hb.id;if(k===key)return;const b=B[k];if(!b)return;if(howLinks.some(l=>l.from===key&&l.to===k))return;boxOpts+='<option value="'+k+'">'+hb.id+' \u2014 '+b.label+'</option>';});if(boxOpts)opts+='<optgroup label="'+sp.label+'">'+boxOpts+'</optgroup>';}else if((sp.pageType||'this_then')==='this_then'&&fromLvl===1){/* V1.0.12.3 (Fix 1): only Level-1 How boxes may hierarchically link to This\u2013Then boxes */let boxOpts='';sp.cols.forEach((col,ci)=>{col.boxes.forEach((_,bi)=>{const k=sp.id+'-c'+ci+'-b'+bi;const b=B[k];if(!b)return;if(howLinks.some(l=>l.from===key&&l.to===k))return;boxOpts+='<option value="'+k+'">'+b.label+'</option>';});});if(boxOpts)opts+='<optgroup label="'+sp.label+' (This\u2013Then)">'+boxOpts+'</optgroup>';}});return '<div style="margin-top:8px"><select class="how-link-sel" id="upHowPopupPicker" style="width:100%">'+opts+'</select></div>';}

function buildUnderBoxDisplay(key,pageType){const vs=pageType==='how'?viewSettings.how:pageType==='finalOutcomes'?viewSettings.finalOutcomes:viewSettings.thisThen;if(!vs)return '';const box=B[key];if(!box)return '';let blocks='';if(vs.showMeasures&&box.measures&&box.measures.length){let items='';box.measures.forEach(mId=>{const m=getMeasure(mId);if(!m)return;items+='<div class="ub-clickable" onclick="openMeasureDetail(\''+m.id+'\')">'+m.id+' '+escHtml(m.title)+'</div>';});if(items)blocks+='<div class="under-box-block"><div class="under-box-block-label">Associated Measures</div>'+items+'</div>';}if(vs.showEvalQuestions&&box.evalQuestions&&box.evalQuestions.length){let items='';box.evalQuestions.forEach(eqId=>{const q=getEQ(eqId);if(!q)return;items+='<div class="ub-clickable" onclick="openEQDetail(\''+q.id+'\')">'+q.id+' '+escHtml(q.questionText)+'</div>';});if(items)blocks+='<div class="under-box-block"><div class="under-box-block-label">Associated Evaluation Questions</div>'+items+'</div>';}if(vs.showMainText&&box.detailText&&box.detailText.trim()){blocks+='<div class="under-box-block"><div class="under-box-block-label">Main text</div>'+linkify(escHtml(box.detailText))+'</div>';}if(!blocks)return '';return '<div class="under-box-wrap">'+blocks+'</div>';}
async function sendChat(){const inp=document.getElementById('chatIn');const msg=inp.value.trim();if(!msg)return;inp.value='';if(msg.toLowerCase()==='undo'){doUndo();return;}addChatMsg('user',msg);addThinking();const history=chatMsgs.slice(-10).filter(m=>m.role!=='system').map(m=>({role:m.role==='asst'?'assistant':m.role,content:m.text}));const wantsFull=/whole board|all pages|across the board|every page|every subpage|all subpages/i.test(msg);const wantsStructural=/add.*(page|subpage|box|column|how)|create|build|new page|new subpage|restructure|how page|how box/i.test(msg);const sysPmt=buildBoardStatePrompt(wantsFull,wantsStructural);
  if(claudeConnected){try{const r=await fetch('https://api.anthropic.com/v1/messages',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({model:'claude-sonnet-4-20250514',max_tokens:1200,system:sysPmt,messages:history,tools:[{type:'web_search_20250305',name:'web_search'}]})});if(r.ok){const d=await r.json();const raw=d.content.filter(b=>b.type==='text').map(b=>b.text).join('\n').replace(/]*>|<\/antml:cite>/g,'');if(raw){const clean=processAIResponse(raw,msg);if(clean){addChatMsg('asst',clean);chatMsgs[chatMsgs.length-1].role='asst';}}removeThinking();}else{removeThinking();addChatMsg('system','Unable to get a response. Please try again.');}}catch(e){removeThinking();addChatMsg('system','Connection error. Please check your network.');}}
  else if(aiSettings.endpoint&&aiSettings.key){try{const fetchUrl=_proxiedUrl(aiSettings.endpoint,aiSettings.proxyUrl||'');const r=await fetch(fetchUrl,{method:'POST',headers:{'Content-Type':'application/json','Authorization':`Bearer ${aiSettings.key}`},body:JSON.stringify({model:aiSettings.model||'gpt-4o',messages:[{role:'system',content:sysPmt},...history],max_tokens:1200})});if(r.ok){const d=await r.json();const raw=d.choices?.[0]?.message?.content||'';if(raw){const clean=processAIResponse(raw,msg);if(clean){addChatMsg('asst',clean);chatMsgs[chatMsgs.length-1].role='asst';}}removeThinking();}else{removeThinking();addChatMsg('system','API error. Check your settings.');}}catch(e){removeThinking();const hint=(!aiSettings.proxyUrl&&/Failed to fetch|NetworkError/i.test(e.message))?' (CORS — try setting a CORS proxy URL in profile settings)':'';addChatMsg('system','Connection error. Check settings.'+hint);}}
  else{removeThinking();addChatMsg('system','No AI connected. Click ⚙️ to configure an API endpoint, or use this board within an AI chat that supports automatic connection.');}}

function openAIChatBox(key){entryMode='chat';if(!document.getElementById('chatPanel').classList.contains('open'))toggleChat();const inp=document.getElementById('chatIn');if(inp){inp.value=`[About: ${B[key].label}] `;inp.focus();}}
// V1.0.14.3: Multi-profile AI Connection Settings + optional CORS proxy. The chat now stores a list of named connection profiles (endpoint + key + model + proxyUrl), with one marked active. aiSettings always mirrors the active profile so the existing sendChat() / status code keeps working unchanged. Profiles persist to localStorage as doview_ai_profiles when "Remember profiles in this browser" is ticked. The optional proxyUrl per profile lets browser clients reach providers (Sovereign Engine, self-hosted gateways) that lock CORS to same-origin: when set, fetches go through the proxy. {url} placeholder gets URL-encoded; otherwise the proxy prefix is concatenated to the endpoint.
function _genAIProfileId(){return 'ai_'+Date.now()+'_'+Math.random().toString(36).substr(2,5);}
function _persistAIProfiles(){try{const cb=document.getElementById('rememberAI');if(cb&&!cb.checked){localStorage.removeItem('doview_ai_profiles');localStorage.removeItem('doview_ai_settings');return;}localStorage.setItem('doview_ai_profiles',JSON.stringify({profiles:aiProfiles,activeId:activeProfileId}));}catch(e){}}
function _applyActiveAIProfile(){const p=aiProfiles.find(x=>x.id===activeProfileId);if(p){aiSettings={endpoint:p.endpoint||'',key:p.key||'',model:p.model||'gpt-4o',proxyUrl:p.proxyUrl||''};}else{aiSettings={};}_updateChatStatus();}
function _updateChatStatus(){const el=document.getElementById('chatStatus');if(!el)return;if(claudeConnected){el.textContent='Connected via the AI chat';return;}if(aiSettings.endpoint){const p=aiProfiles.find(x=>x.id===activeProfileId);el.textContent='✓ Connected'+(p&&p.name?': '+p.name:'');}else{el.textContent='Click ⚙️ to connect an AI';}}
function _escAttr(s){return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');}
function _proxiedUrl(endpoint, proxy){if(!proxy)return endpoint;if(proxy.indexOf('{url}')>=0)return proxy.replace('{url}',encodeURIComponent(endpoint));return proxy+endpoint;}
function renderAIProfilesList(){const list=document.getElementById('aiProfList');if(!list)return;if(!aiProfiles.length){list.innerHTML='<div class="ai-prof-empty">No saved profiles yet. Click + New profile to add one.</div>';return;}let html='';aiProfiles.forEach(p=>{const isActive=p.id===activeProfileId;const ep=_escAttr(p.endpoint||'');const md=_escAttr(p.model||'');const nm=_escAttr(p.name||'(unnamed)');const idEsc=_escAttr(p.id);const proxyTag=p.proxyUrl?' <span style="color:var(--orange);font-weight:600" title="'+_escAttr(p.proxyUrl)+'">· via CORS proxy</span>':'';html+='<div class="ai-prof-item'+(isActive?' active':'')+'">'+'<div class="ai-prof-row">'+'<label class="ai-prof-radio" title="Set as active profile"><input type="radio" name="aiProfActive" '+(isActive?'checked':'')+' onchange="setActiveProfile(\''+idEsc+'\')"> Active</label>'+'<div class="ai-prof-name">'+nm+'</div>'+'<div class="ai-prof-actions">'+'<button class="ai-prof-btn" onclick="editProfile(\''+idEsc+'\')">Edit</button>'+'<button class="ai-prof-btn danger" onclick="deleteProfile(\''+idEsc+'\')">Delete</button>'+'</div></div>'+'<div class="ai-prof-meta">'+(ep||'(no endpoint)')+(md?'  ·  '+md:'')+proxyTag+'</div>'+'</div>';});list.innerHTML=html;}
function setActiveProfile(id){if(!aiProfiles.find(x=>x.id===id))return;activeProfileId=id;_applyActiveAIProfile();_persistAIProfiles();renderAIProfilesList();claudeConnected=false;_updateChatStatus();}
function addNewProfile(){editingProfileId=null;document.getElementById('aiProfEditTitle').textContent='New profile';document.getElementById('setName').value='';document.getElementById('setEP').value='';document.getElementById('setKey').value='';document.getElementById('setModel').value='';document.getElementById('setProxy').value='';const r=document.getElementById('connTestResult');r.textContent='';r.style.color='var(--text2)';document.getElementById('aiProfEdit').style.display='flex';document.getElementById('aiProfAddBtn').style.display='none';document.getElementById('setName').focus();}
function editProfile(id){const p=aiProfiles.find(x=>x.id===id);if(!p)return;editingProfileId=id;document.getElementById('aiProfEditTitle').textContent='Edit profile';document.getElementById('setName').value=p.name||'';document.getElementById('setEP').value=p.endpoint||'';document.getElementById('setKey').value=p.key||'';document.getElementById('setModel').value=p.model||'';document.getElementById('setProxy').value=p.proxyUrl||'';const r=document.getElementById('connTestResult');r.textContent='';r.style.color='var(--text2)';document.getElementById('aiProfEdit').style.display='flex';document.getElementById('aiProfAddBtn').style.display='none';document.getElementById('setName').focus();}
function cancelProfileEdit(){editingProfileId=null;const ed=document.getElementById('aiProfEdit');if(ed)ed.style.display='none';const ab=document.getElementById('aiProfAddBtn');if(ab)ab.style.display='';const r=document.getElementById('connTestResult');if(r){r.textContent='';r.style.color='var(--text2)';}}
function deleteProfile(id){const p=aiProfiles.find(x=>x.id===id);if(!p)return;if(!confirm('Delete profile "'+(p.name||'(unnamed)')+'"?'))return;aiProfiles=aiProfiles.filter(x=>x.id!==id);if(activeProfileId===id){activeProfileId=aiProfiles.length?aiProfiles[0].id:null;}_applyActiveAIProfile();_persistAIProfiles();renderAIProfilesList();if(editingProfileId===id)cancelProfileEdit();claudeConnected=false;_updateChatStatus();}
function onRememberToggle(){_persistAIProfiles();}
function saveChatSettings(){const name=document.getElementById('setName').value.trim();const ep=document.getElementById('setEP').value.trim();const key=document.getElementById('setKey').value.trim();const model=document.getElementById('setModel').value.trim()||'gpt-4o';const proxyUrl=document.getElementById('setProxy').value.trim();const res=document.getElementById('connTestResult');if(!ep){res.style.color='#ef4444';res.textContent='API Endpoint is required.';return;}const finalName=name||(ep.replace(/^https?:\/\//,'').split('/')[0]+(model?' '+model:''));let p=null;if(editingProfileId){p=aiProfiles.find(x=>x.id===editingProfileId);if(p){p.name=finalName;p.endpoint=ep;p.key=key;p.model=model;p.proxyUrl=proxyUrl;}}if(!p){p={id:_genAIProfileId(),name:finalName,endpoint:ep,key:key,model:model,proxyUrl:proxyUrl};aiProfiles.push(p);}activeProfileId=p.id;editingProfileId=null;_applyActiveAIProfile();_persistAIProfiles();renderAIProfilesList();document.getElementById('aiProfEdit').style.display='none';document.getElementById('aiProfAddBtn').style.display='';claudeConnected=false;_updateChatStatus();}
async function testChatConn(){const ep=document.getElementById('setEP').value.trim();const key=document.getElementById('setKey').value.trim();const model=document.getElementById('setModel').value.trim()||'gpt-4o';const proxyUrl=document.getElementById('setProxy').value.trim();const res=document.getElementById('connTestResult');if(!ep){res.style.color='#ef4444';res.textContent='Enter an API Endpoint first.';return;}const fetchUrl=_proxiedUrl(ep,proxyUrl);res.textContent='Testing'+(proxyUrl?' (via proxy)':'')+'…';res.style.color='var(--text2)';try{const r=await fetch(fetchUrl,{method:'POST',headers:{'Content-Type':'application/json','Authorization':`Bearer ${key}`},body:JSON.stringify({model,messages:[{role:'user',content:'hi'}],max_tokens:10})});res.textContent=r.ok?'✓ Connected successfully!':`Error: ${r.status} ${r.statusText}`;res.style.color=r.ok?'#22c55e':'#ef4444';}catch(e){const hint=(!proxyUrl&&/Failed to fetch|NetworkError/i.test(e.message))?' — likely CORS. Try a CORS proxy URL above.':'';res.textContent='Connection failed: '+e.message+hint;res.style.color='#ef4444';}}
async function probeConnection(){try{const r=await fetch('https://api.anthropic.com/v1/messages',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({model:'claude-sonnet-4-20250514',max_tokens:5,messages:[{role:'user',content:'hi'}]})});if(r.status===200){claudeConnected=true;}}catch(e){}_updateChatStatus();}

