// ─── GLOBAL SEARCH V1 ───
function openGlobalSearch(){openModal('globalSearchModal');var inp=document.getElementById('globalSearchInput');inp.value='';document.getElementById('globalSearchResults').innerHTML='<div style="color:var(--text2);font-style:italic;padding:8px">Type to search page titles, box titles, main text, measures, evaluation questions, documentation content, and link text.</div>';setTimeout(function(){inp.focus();},100);}
function doGlobalSearch(){var q=document.getElementById('globalSearchInput').value.trim().toLowerCase();var container=document.getElementById('globalSearchResults');if(!q||q.length<2){container.innerHTML='<div style="color:var(--text2);font-style:italic;padding:8px">Type at least 2 characters.</div>';return;}var results=[];var esc=function(s){var d=document.createElement('div');d.textContent=s;return d.innerHTML;};var snippet=function(text,term){var lower=text.toLowerCase();var idx=lower.indexOf(term);if(idx<0)return text.substring(0,80)+(text.length>80?'…':'');var start=Math.max(0,idx-30);var end=Math.min(text.length,idx+term.length+50);var s=(start>0?'…':'')+text.substring(start,end)+(end<text.length?'…':'');return s;};
// Search page titles
SP.forEach(function(sp){if(sp.label.toLowerCase().indexOf(q)>=0){results.push({type:'Page title',page:sp.label,id:'',snippet:sp.label,action:'navTo(\''+sp.id+'\')'});}});
if('final outcomes'.indexOf(q)>=0){results.push({type:'Page title',page:'Final Outcomes',id:'',snippet:'Final Outcomes',action:'navTo(\'final\')'});}
// Search box titles and main text (This-Then)
SP.forEach(function(sp){if(sp.pageType==='documentation')return;if(sp.pageType==='how'&&sp.howBoxes){sp.howBoxes.forEach(function(hb){var k=sp.id+'-'+hb.id;var bd=B[k];if(!bd)return;if(bd.label.toLowerCase().indexOf(q)>=0){results.push({type:'How box',page:sp.label,id:hb.id,snippet:bd.label,action:'searchNavBox(\''+sp.id+'\',\''+k+'\')'});}if(bd.detailText&&bd.detailText.toLowerCase().indexOf(q)>=0){results.push({type:'How box main text',page:sp.label,id:hb.id,snippet:snippet(bd.detailText,q),action:'searchNavBox(\''+sp.id+'\',\''+k+'\')'});}});return;}sp.cols.forEach(function(col,ci){col.boxes.forEach(function(_,bi){var k=sp.id+'-c'+ci+'-b'+bi;var bd=B[k];if(!bd)return;if(bd.label.toLowerCase().indexOf(q)>=0){results.push({type:'This–Then box',page:sp.label,id:'',snippet:bd.label,action:'searchNavBox(\''+sp.id+'\',\''+k+'\')'});}if(bd.detailText&&bd.detailText.toLowerCase().indexOf(q)>=0){results.push({type:'Box main text',page:sp.label,id:'',snippet:snippet(bd.detailText,q),action:'searchNavBox(\''+sp.id+'\',\''+k+'\')'});}});});});
// Final outcomes
FO_DATA.forEach(function(label,i){var k='final-b'+i;var bd=B[k];if(!bd)return;if(label.toLowerCase().indexOf(q)>=0){results.push({type:'Final Outcome',page:'Final Outcomes',id:'',snippet:label,action:'searchNavBox(\'final\',\''+k+'\')'});}if(bd.detailText&&bd.detailText.toLowerCase().indexOf(q)>=0){results.push({type:'Final Outcome main text',page:'Final Outcomes',id:'',snippet:snippet(bd.detailText,q),action:'searchNavBox(\'final\',\''+k+'\')'});}});
// Measures
measures.forEach(function(m){if(m.title.toLowerCase().indexOf(q)>=0){results.push({type:'Measure',page:'',id:m.id,snippet:m.title,action:'closeModal(\'globalSearchModal\');openMeasureDetail(\''+m.id+'\')'});}if(m.mainText&&m.mainText.toLowerCase().indexOf(q)>=0){results.push({type:'Measure text',page:'',id:m.id,snippet:snippet(m.mainText,q),action:'closeModal(\'globalSearchModal\');openMeasureDetail(\''+m.id+'\')'});}});
// Evaluation Questions
evalQuestions.forEach(function(eq){if(eq.questionText.toLowerCase().indexOf(q)>=0){results.push({type:'Eval Question',page:'',id:eq.id,snippet:eq.questionText,action:'closeModal(\'globalSearchModal\');openEQDetail(\''+eq.id+'\')'});}if(eq.mainText&&eq.mainText.toLowerCase().indexOf(q)>=0){results.push({type:'EQ text',page:'',id:eq.id,snippet:snippet(eq.mainText,q),action:'closeModal(\'globalSearchModal\');openEQDetail(\''+eq.id+'\')'});}});
// Documentation page content
SP.forEach(function(sp){if(sp.pageType!=='documentation')return;var dc=docContent[sp.id]||'';var plain=dc.replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();if(plain.toLowerCase().indexOf(q)>=0){results.push({type:'Documentation',page:sp.label,id:'',snippet:snippet(plain,q),action:'closeModal(\'globalSearchModal\');navTo(\''+sp.id+'\')'});}});
// Link text
ttLinks.forEach(function(l){var fb=B[l.from];var tb=B[l.to];if(!fb||!tb)return;if(l.mainText&&l.mainText.toLowerCase().indexOf(q)>=0){results.push({type:'TT Link text',page:'',id:l.id,snippet:snippet(l.mainText,q),action:'closeModal(\'globalSearchModal\');openLinkDetail(\''+l.id+'\')'});}});
howLinks.forEach(function(l){var fb=B[l.from];var tb=B[l.to];if(!fb||!tb)return;if(l.mainText&&l.mainText.toLowerCase().indexOf(q)>=0){results.push({type:'How Link text',page:'',id:l.id,snippet:snippet(l.mainText,q),action:'closeModal(\'globalSearchModal\');openLinkDetail(\''+l.id+'\')'});}});
if(!results.length){container.innerHTML='<div style="color:var(--text2);font-style:italic;padding:8px">No results found.</div>';return;}
container.innerHTML=results.slice(0,50).map(function(r){return '<div style="padding:6px 8px;border-bottom:1px solid #f1f5f9;cursor:pointer;border-radius:4px" onmouseover="this.style.background=\'#f8fafc\'" onmouseout="this.style.background=\'transparent\'" onclick="'+r.action+'"><div style="display:flex;gap:8px;align-items:center;margin-bottom:2px"><span style="font-size:10px;font-weight:600;color:#F5A623;text-transform:uppercase">'+esc(r.type)+'</span>'+(r.id?'<span style="font-size:10px;color:var(--text2);font-weight:600">'+esc(r.id)+'</span>':'')+(r.page?'<span style="font-size:10px;color:var(--text2)">'+esc(r.page)+'</span>':'')+'</div><div style="color:#1e293b;font-size:11.5px;line-height:1.4">'+esc(r.snippet)+'</div></div>';}).join('');}
function searchNavBox(pageId,boxKey){closeModal('globalSearchModal');navTo(pageId);setTimeout(function(){clickBox(boxKey);var el=document.getElementById('bx-'+boxKey);if(el)el.scrollIntoView({behavior:'smooth',block:'center'});},100);}

// ─── LINK DETAILS & REGISTRY ───
function findLink(linkId){var l=ttLinks.find(function(x){return x.id===linkId;});if(l)return{link:l,type:'this_then'};l=howLinks.find(function(x){return x.id===linkId;});if(l)return{link:l,type:'how'};return null;}
function ensureLinkFields(l){if(!l.mainText)l.mainText='';if(!l.notes1)l.notes1='';if(!l.notes2)l.notes2='';if(!l.notes3)l.notes3='';}
// FIX 4 (V1.0.12.1): Measures and Evaluation Questions can be attached to This–Then links only (not How links at this stage). Arrays default to [] for older saved boards.
function ensureTTLinkMEQFields(l){if(!Array.isArray(l.measures))l.measures=[];if(!Array.isArray(l.evalQuestions))l.evalQuestions=[];}
function buildLinkMeasuresSection(linkId){var found=findLink(linkId);if(!found||found.type!=='this_then')return '';var l=found.link;ensureTTLinkMEQFields(l);var linked=l.measures||[];var items='';linked.forEach(function(mId){var m=getMeasure(mId);if(!m)return;items+='<div class="meq-item"><span class="meq-item-id">'+m.id+'</span><span class="meq-item-title" onclick="closeModal(\'linkDetailModal\');openMeasureDetail(\''+m.id+'\')">'+escHtml(m.title)+'</span><span class="meq-item-rm" onclick="unlinkMeasureFromTTLink(\''+m.id+'\',\''+linkId+'\')" title="Remove association">\u2715</span></div>';});var opts='<option value="">Select a measure\u2026</option>';measures.forEach(function(m){if(!linked.includes(m.id))opts+='<option value="'+m.id+'">'+m.id+' \u2014 '+escHtml(m.title)+'</option>';});return '<div class="meq-section"><div class="meq-hdr">Associated Measures</div>'+(items||'<div style="font-size:10px;color:var(--text2);font-style:italic;margin-bottom:4px">None associated</div>')+'<div class="meq-add"><select class="meq-sel" id="linkMPicker">'+opts+'</select><button class="meq-abtn" onclick="addMeasureFromLinkPicker(\''+linkId+'\')" title="Associate with this structural link">Associate</button></div><div class="meq-footer"><span class="meq-footer-link" onclick="createNewMeasureForLink(\''+linkId+'\')">Create new measure</span><span class="meq-footer-link" onclick="openMeasuresRegistry()">View all measures</span></div></div>';}
function buildLinkEQSection(linkId){var found=findLink(linkId);if(!found||found.type!=='this_then')return '';var l=found.link;ensureTTLinkMEQFields(l);var linked=l.evalQuestions||[];var items='';linked.forEach(function(eqId){var q=getEQ(eqId);if(!q)return;items+='<div class="meq-item"><span class="meq-item-id">'+q.id+'</span><span class="meq-item-title" onclick="closeModal(\'linkDetailModal\');openEQDetail(\''+q.id+'\')">'+escHtml(q.questionText)+'</span><span class="meq-item-rm" onclick="unlinkEQFromTTLink(\''+q.id+'\',\''+linkId+'\')" title="Remove association">\u2715</span></div>';});var opts='<option value="">Select an evaluation question\u2026</option>';evalQuestions.forEach(function(q){if(!linked.includes(q.id))opts+='<option value="'+q.id+'">'+q.id+' \u2014 '+escHtml(q.questionText)+'</option>';});return '<div class="meq-section"><div class="meq-hdr">Associated Evaluation Questions</div>'+(items||'<div style="font-size:10px;color:var(--text2);font-style:italic;margin-bottom:4px">None associated</div>')+'<div class="meq-add"><select class="meq-sel" id="linkEQPicker">'+opts+'</select><button class="meq-abtn" onclick="addEQFromLinkPicker(\''+linkId+'\')" title="Associate with this structural link">Associate</button></div><div class="meq-footer"><span class="meq-footer-link" onclick="createNewEQForLink(\''+linkId+'\')">Create new evaluation question</span><span class="meq-footer-link" onclick="openEQRegistry()">View all evaluation questions</span></div></div>';}
function linkMeasureToTTLink(mId,linkId){if(IS_READONLY)return;var found=findLink(linkId);if(!found||found.type!=='this_then')return;var l=found.link;ensureTTLinkMEQFields(l);if(!l.measures.includes(mId))l.measures.push(mId);saveState();openLinkDetail(linkId);}
function unlinkMeasureFromTTLink(mId,linkId){if(IS_READONLY)return;var found=findLink(linkId);if(!found||found.type!=='this_then')return;var l=found.link;if(!l.measures)return;l.measures=l.measures.filter(function(id){return id!==mId;});saveState();openLinkDetail(linkId);}
function linkEQToTTLink(eqId,linkId){if(IS_READONLY)return;var found=findLink(linkId);if(!found||found.type!=='this_then')return;var l=found.link;ensureTTLinkMEQFields(l);if(!l.evalQuestions.includes(eqId))l.evalQuestions.push(eqId);saveState();openLinkDetail(linkId);}
function unlinkEQFromTTLink(eqId,linkId){if(IS_READONLY)return;var found=findLink(linkId);if(!found||found.type!=='this_then')return;var l=found.link;if(!l.evalQuestions)return;l.evalQuestions=l.evalQuestions.filter(function(id){return id!==eqId;});saveState();openLinkDetail(linkId);}
function addMeasureFromLinkPicker(linkId){var sel=document.getElementById('linkMPicker');if(!sel||!sel.value)return;linkMeasureToTTLink(sel.value,linkId);}
function addEQFromLinkPicker(linkId){var sel=document.getElementById('linkEQPicker');if(!sel||!sel.value)return;linkEQToTTLink(sel.value,linkId);}
function createNewMeasureForLink(linkId){if(IS_READONLY)return;var found=findLink(linkId);if(!found||found.type!=='this_then')return;var id='M'+String(measureNextId).padStart(3,'0');measureNextId++;/* V1.0.14.2 (Fix 5): assign stable uid to the newly created Measure created from a link picker. */var m={id:id,title:'New measure',mainText:'',notes1:'',notes2:'',notes3:'',uid:_genUid('measure')};measures.push(m);var l=found.link;ensureTTLinkMEQFields(l);if(!l.measures.includes(id))l.measures.push(id);saveState();closeModal('linkDetailModal');openMeasureDetail(id);render();}
function createNewEQForLink(linkId){if(IS_READONLY)return;var found=findLink(linkId);if(!found||found.type!=='this_then')return;var id='EQ'+String(eqNextId).padStart(3,'0');eqNextId++;/* V1.0.14.2 (Fix 5): assign stable uid to the newly created Evaluation Question created from a link picker. */var q={id:id,questionText:'New evaluation question',mainText:'',notes1:'',notes2:'',notes3:'',uid:_genUid('eq')};evalQuestions.push(q);var l=found.link;ensureTTLinkMEQFields(l);if(!l.evalQuestions.includes(id))l.evalQuestions.push(id);saveState();closeModal('linkDetailModal');openEQDetail(id);render();}
function getTTLinksLinkedToMeasure(mId){return ttLinks.filter(function(l){return l.measures&&l.measures.includes(mId);});}
function getTTLinksLinkedToEQ(eqId){return ttLinks.filter(function(l){return l.evalQuestions&&l.evalQuestions.includes(eqId);});}
/* V1.0.14.2 (Fix 9): _meqEditField returns either the editable surface (textarea or input) for editable boards OR a read-only display block (with clickable URLs) for read-only copies. Replaces the previous "display block above + textarea below" duplication so editable popups show the edit surface only and read-only popups show the rendered text only. URLs in the read-only display remain clickable via buildPopupDisplayBlock. */
function _meqEditField(text,fieldId,kind,rows){var s=text===null||text===undefined?'':String(text);if(IS_READONLY){if(s.trim()===''){return '<div class="meq-detail-display" style="font-style:italic;color:var(--text2)">(empty)</div>';}return buildPopupDisplayBlock(s,'');}if(kind==='input'){return '<input id="'+fieldId+'" value="'+escAttr(s)+'">';}return '<textarea id="'+fieldId+'" rows="'+(rows||3)+'">'+escHtml(s)+'</textarea>';}
/* V1.0.14.2 (Fix 10): deleteLinkFromDetail removes a structural link (This\u2013Then or How) from the link detail popup, with a clear plain-language confirmation. Removes only the link itself (and any link-level Measure/EQ associations attached to that link); leaves source box, target box, and board-level Measures/Evaluation Questions untouched. Hidden in read-only copies. */
function deleteLinkFromDetail(){if(IS_READONLY)return;var modal=document.getElementById('linkDetailModal');if(!modal)return;var linkId=modal.dataset.linkId;if(!linkId)return;var found=findLink(linkId);if(!found)return;var l=found.link;var fb=B[l.from];var tb=B[l.to];var fromLabel=fb?fb.label:l.from;var toLabel=tb?tb.label:l.to;if(!confirm('Delete this link from "'+fromLabel+'" to "'+toLabel+'"?'))return;takeSnapshot();if(found.type==='this_then'){var idx=ttLinks.findIndex(function(x){return x.id===linkId;});if(idx>=0)ttLinks.splice(idx,1);}else{var idx2=howLinks.findIndex(function(x){return x.id===linkId;});if(idx2>=0)howLinks.splice(idx2,1);}saveState();closeModal('linkDetailModal');render();}
function openLinkDetail(linkId){var found=findLink(linkId);if(!found)return;var l=found.link;var lt=found.type;ensureLinkFields(l);if(lt==='this_then')ensureTTLinkMEQFields(l);var fb=B[l.from];var tb=B[l.to];var fromLabel=fb?fb.label:l.from;var toLabel=tb?tb.label:l.to;var typeLabel=lt==='this_then'?'This\u2013Then Link':'How Link';document.getElementById('linkDetailTitle').innerHTML='<i>'+escHtml(fromLabel)+'</i> \u2192<br><i>'+escHtml(toLabel)+'</i>';var html='<div style="font-size:10.5px;color:var(--text2);margin-bottom:10px"><span style="font-size:9px;font-weight:600;color:#fff;padding:2px 6px;border-radius:3px;background:'+(lt==='this_then'?'#F5A623':'#60a5fa')+'">'+typeLabel+'</span></div>';/* V1.0.14.2 (Fix 9): editable popups show the textarea only; read-only copies show only the rendered display block. */html+='<div class="meq-detail-field"><label>Main text</label>'+_meqEditField(l.mainText,'linkDMain','textarea',3)+'</div>';html+='<div class="meq-detail-field"><label>Notes 1</label>'+_meqEditField(l.notes1,'linkDN1','textarea',2)+'</div>';html+='<div class="meq-detail-field"><label>Notes 2</label>'+_meqEditField(l.notes2,'linkDN2','textarea',2)+'</div>';html+='<div class="meq-detail-field"><label>Notes 3</label>'+_meqEditField(l.notes3,'linkDN3','textarea',2)+'</div>';if(lt==='this_then'){html+=buildLinkMeasuresSection(linkId);html+=buildLinkEQSection(linkId);}/* V1.0.14.2 (Fix 10): consistent Delete link button at the bottom of the link detail popup, in editable boards only. */if(!IS_READONLY){html+='<div style="margin-top:12px;padding-top:10px;border-top:1px solid var(--bdr)"><button class="ep-sbtn ep-del" onclick="deleteLinkFromDetail()">Delete link</button></div>';}document.getElementById('linkDetailContent').innerHTML=html;document.getElementById('linkDetailModal').dataset.linkId=linkId;openModal('linkDetailModal');}
function saveLinkDetail(){if(IS_READONLY){closeModal('linkDetailModal');return;}var linkId=document.getElementById('linkDetailModal').dataset.linkId;var found=findLink(linkId);if(!found){closeModal('linkDetailModal');return;}var l=found.link;l.mainText=(document.getElementById('linkDMain')||{}).value||'';l.notes1=(document.getElementById('linkDN1')||{}).value||'';l.notes2=(document.getElementById('linkDN2')||{}).value||'';l.notes3=(document.getElementById('linkDN3')||{}).value||'';saveState();closeModal('linkDetailModal');render();}
function openLinksRegistry(){var html='';var allLinks=[];ttLinks.forEach(function(l){var fb=B[l.from];var tb=B[l.to];if(!fb||!tb)return;var fpg=getBoxPage(l.from);var tpg=getBoxPage(l.to);allLinks.push({id:l.id,type:'this_then',typeLabel:'This\u2013Then',from:fb.label,to:tb.label,fromPage:fpg?fpg.label:'',toPage:tpg?tpg.label:'',snippet:l.mainText||''});});/* V1.0.13.1 (Fix 3): the top Links menu lists structural box-to-box links only and now distinguishes non-up-and-down structural links with a Non-up/down badge. classifyHowLink returns 'upward' / 'downward' (kept under the existing How badge) or 'lateral' (rendered with the new Non-up/down badge and nud-type CSS class). The internal classifier value 'lateral' is unchanged; only the user-facing badge wording is changed. The Other links wording is intentionally not used. */howLinks.forEach(function(l){var fb=B[l.from];var tb=B[l.to];if(!fb||!tb)return;var fpg=getBoxPage(l.from);var tpg=getBoxPage(l.to);var cls=classifyHowLink(l.from,l.to);var isLat=(cls==='lateral');allLinks.push({id:l.id,type:isLat?'nud':'how',typeLabel:isLat?'Non-up/down':'How',from:fb.label,to:tb.label,fromPage:fpg?fpg.label:'',toPage:tpg?tpg.label:'',snippet:l.mainText||''});});if(!allLinks.length){html='<div style="color:var(--text2);font-style:italic;padding:8px 0">No links created yet.</div>';}else{allLinks.forEach(function(r){var snip=r.snippet?'<span class="link-reg-snippet" title="'+escAttr(r.snippet)+'">'+escHtml(r.snippet.substring(0,40))+(r.snippet.length>40?'\u2026':'')+'</span>':'';var typeCls=r.type==='this_then'?'tt-type':(r.type==='how'?'how-type':'nud-type');html+='<div class="link-reg-item" onclick="closeModal(\'linksRegistryModal\');openLinkDetail(\''+r.id+'\')"><span class="link-reg-type '+typeCls+'">'+r.typeLabel+'</span><span class="link-reg-box" title="'+escAttr(r.from)+'">'+escHtml(r.from)+'</span><span class="link-reg-arrow">\u2192</span><span class="link-reg-box" title="'+escAttr(r.to)+'">'+escHtml(r.to)+'</span><span class="link-reg-pg">'+escHtml(r.fromPage)+(r.fromPage!==r.toPage?' / '+escHtml(r.toPage):'')+'</span>'+snip+'</div>';});}document.getElementById('linksRegistryList').innerHTML=html;openModal('linksRegistryModal');}

